import { fmt, n, q, num, L, U } from "./ee-shape.mjs";

const vin = 10;
const r1 = 2000;
const r2 = 3000;
const vNom = vin * r2 / (r1 + r2);
const vHi = vin * 3030 / (1980 + 3030);
const vLo = vin * 2970 / (2020 + 2970);
const span = vHi - vLo;
const dR1 = 20;
const dR2 = 30;
const sens1 = -vin * r2 / (r1 + r2) ** 2;
const sens2 = vin * r1 / (r1 + r2) ** 2;
const vLinear = vNom + sens1 * -dR1 + sens2 * dR2;

function lcg(seed) {
  let s = seed >>> 0;
  return () => {
    s = (Math.imul(1664525, s) + 1013904223) >>> 0;
    return s / 4294967296;
  };
}
const next = lcg(20261114);
const samples = [];
for (let i = 0; i < 8; i += 1) {
  const a = r1 * (1 + 0.01 * (2 * next() - 1));
  const b = r2 * (1 + 0.01 * (2 * next() - 1));
  samples.push((vin * b) / (a + b));
}
const mcMin = Math.min(...samples);
const mcMax = Math.max(...samples);
const mcMean = samples.reduce((sum, v) => sum + v, 0) / samples.length;

const vSrc = 10;
const rNom = 100;
const rMin = 95;
const rMax = 105;
const iHi = vSrc / rMin;
const iLo = vSrc / rMax;
const pHi = (vSrc * vSrc) / rMin;
const pLo = (vSrc * vSrc) / rMax;

const vinB = 5;
const vHiB = vinB * 1020 / 2000;
const vLoB = vinB * 980 / 2000;

const openBottom = 10;
const openTop = 0;
const rLoad = 1500;
const vLoaded = vin * rLoad / (r1 + rLoad);
const vTwelve = 12 * r2 / (r1 + r2);

const lTrace = 20e-9;
const diDt = 1e8;
const vSpike = lTrace * diDt;
const rTrace = 0.01;
const iDc = 2;
const vResist = rTrace * iDc;
const lEsl = 2e-9;
const cDec = 100e-9;
const fRes = 1 / (2 * Math.PI * Math.sqrt(lEsl * cDec));
const eps0 = 8.854187817e-12;
const cPlane = (eps0 * 4.5 * 0.01) / 0.0002;
const lMutual = 5e-9;
const vCross = lMutual * diDt;
const vVia = 1e-9 * diDt;

